package com.mr_leaves.mlsg.ad_fabric.screen;

import com.mojang.blaze3d.platform.NativeImage;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.texture.DynamicTexture;
import net.minecraft.resources.ResourceLocation;

import java.io.ByteArrayInputStream;
import java.util.Base64;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * 内嵌 Logo 纹理：把 64x64 的 ML5G logo 以 base64 形式编入代码，
 * 运行时解码并注册为动态纹理。不依赖 Fabric API / mod 资源包挂载。
 */
public final class EmbeddedLogo {
    private static final Logger LOGGER = LoggerFactory.getLogger(EmbeddedLogo.class);

    public static final ResourceLocation TEXTURE =
            ResourceLocation.fromNamespaceAndPath("mlsg_ad_fabric", "textures/gui/embedded_logo");

    private static final String BASE64 =
            "";

    private static boolean registered = false;

    private EmbeddedLogo() {
    }

    /** 首次渲染时注册并上传纹理（只执行一次） */
    public static void ensureRegistered() {
        if (registered) return;
        registered = true;
        try {
            byte[] data = Base64.getDecoder().decode(BASE64);
            NativeImage image = NativeImage.read(new ByteArrayInputStream(data));
            DynamicTexture texture = new DynamicTexture(image);
            texture.upload();
            Minecraft.getInstance().getTextureManager().register(TEXTURE, texture);
            LOGGER.info("MLSG AD: embedded logo texture registered.");
        } catch (Exception e) {
            // 失败只记日志，不让广告条目影响游戏运行
            LOGGER.error("MLSG AD: failed to embed logo texture", e);
        }
    }

    /** 资源重载（如 F3+T）后动态纹理会被销毁，需要重置以便下次重新注册 */
    public static void reset() {
        registered = false;
    }
}
